---FreshUI
---刷新签到格子
---@param data table
---@param index number
---@param dialog userdata
function SignCellNode:FreshUI(data, index , dialog)
    self.dialog = dialog
    local playerDojo = PlayerComponent.playerDojo
    local dailySignIn = playerDojo.dailySignIn
    local signInDays =  checkInt(dailySignIn.signInDays)
    local dailyDrawStatus = checkInt(dailySignIn.dailyDrawStatus)
    local mod = signInDays % 7 
    local times = math.floor(signInDays / 7 ) 
    -- 当是7 的倍数 并且 不是第零天
    local Get = self.controller.transform:Find("Root/Get")   
    local ImgBg = self.controller.transform:Find("Root/Normal/ImgBg")   
    local Received = self.controller.transform:Find("Root/Received")
    local Txtdate = self.controller.transform:Find("Root/Normal/Txtdate")  
    CfUtils.FillText(Txtdate , "0" .. index)
    if mod >= index then
        KTool.SetActive(Received.gameObject , true)  
        KTool.SetActive(Get , false)  
    else 
        if dailyDrawStatus == 0 and mod +1 == index then
            KTool.SetActive(Received.gameObject , false)  
            KTool.SetActive(Get , true)
            GameUtils.Request(Interfaces.SignIn, {}, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local data = response.data 
                    GoodsUtils.DrawRewards(data.rewards , true)
                    dailySignIn.signInDays = dailySignIn.signInDays + 1
                    local treasureDays = checkInt(dailySignIn.treasureDays) 
                    local treasureRewards = dailySignIn.treasureRewards
                    local countDay = checkInt( treasureRewards[#treasureRewards].times)
                    dailySignIn.treasureDays = treasureDays >= countDay and countDay or  (treasureDays + 1)
                    dailySignIn.dailyDrawStatus = 1
                    CfUtils.StartCoroutineWithBlocker(function()
                        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
                        UIModule.OpenDialog(
                            {
                                id = Constants.UITypeIds.UICommonRewardPop,
                                parameters = { rewards = data.rewards , cb = function()
                                    if checkInt(dailySignIn.signInDays) % 7 == 0 then
                                        CfUtils.PlayAnimation(self.RefreshNode  , "DailyCheck_Refresh")
                                        self.dialog:RefreshHome()
                                    else 
                                        CfUtils.PlayAnimation(self.controller.gameObject , "DailyChecked")
                                        self:FreshUI(data, index , self.dialog)
                                        self.dialog:UpdateDayCellNodeByIndex(index + 1)
                                    end
                                    self.dialog:UpdatePrograss(true)
                                    PlayerComponent:CheckPlayerSignInBox()
                                end}
                            }
                        )          
                    end)    
                end
            end) 
        else
            if mod +1 == index then
                self.dialog:UpdateShowTextGet()
            end
            KTool.SetActive(Received.gameObject , false)  
            KTool.SetActive(Get , false)    
        end
    end

    for i = 1, #data.rewards do
        local GoodNode = self.ImgGoodFrame.transform:Find("GoodNode" .. i)    
        if isNotNull(GoodNode) then
            local reward = data.rewards[i]
            ---@type GoodNodeMB
            local GoodNodeEnv = CfUtils.GetLuaScr(GoodNode.gameObject, "Game.Behaviours.GoodNodeMB")
            GoodNodeEnv:Reload(
                {
                    goodsId = reward.goodsId,
                    isShowNo = true, text = "x" .. reward.num 
                }
            )
            GoodNodeEnv:SetClickCallback(function()
                local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(reward.goodsId)
                if isTable(vo) then
                    GameUtils.ShowCommonTipsBoard(GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
                end
            end)
        end
    end
end
function SignCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self.dialog = nil
    self:Delete()
    self = nil
end

return SignCellNode